mapper.select:
/* Baim01Mapper.selectSiteInfoList */ SELECT '' AS chk , A.SITE_CD AS siteCd , A.SITE_NO AS siteNo , A.SITE_NM AS siteNm , A.CMPNY_CD AS cmpnyCd , A.ADDR_1 AS addr1 , A.ADDR_2 AS addr2 , A.ZIP_CODE AS zipCode , A.STR_DATE AS strDate , A.END_DATE AS endDate , A.USE_YN AS useYn , A.SITE_ADMIN_CD AS siteAdminCd , B.USER_NM AS siteAdminNm , A.TEL_NO AS telNo , IFNULL(A.GPS_RANGE, 0) AS gpsRange , A.SITE_DESC AS siteDesc , A.LAT AS lat , A.LON AS lon
, A.LINK_SRC_CMPNY_CD AS linkSrcCmpnyCd FROM TB_SITE A LEFT JOIN TB_USER B ON ( A.CMPNY_CD = B.CMPNY_CD AND A.SITE_ADMIN_CD = B.USER_CD ) WHERE 1=1 AND A.CMPNY_CD = #{gvCmpnyCd}
AND A.SITE_CD = #{siteCd}
AND A.SITE_NO = #{siteNo}
AND A.SITE_NM LIKE CONCAT('%', #{siteNm}, '%')
AND A.USE_YN = #{useYn}

mapper.insert:
/* Baim01Mapper.insertSiteNodeInfo */
INSERT INTO TB_SITE_NODE(
	CMPNY_CD
	, SITE_CD
	, NODE_CD
	, NODE_NM
	, NODE_TYPE

	, SELF_ATTD_APPRV_YN
	, INSERT_NO
	, INSERT_DATE
	, UPDATE_NO
	, UPDATE_DATE
)
VALUES(
	#{gvCmpnyCd}
	, #{siteCd}
	, #{nodeCd}
	, #{nodeNm}
	, #{nodeType}
	, CASE WHEN #{nodeCd} = 'n1' THEN 'Y' ELSE 'N' END
	, #{gvUserCd}
	, NOW()
	, #{gvUserCd}
	, NOW()
) AS NEW
ON DUPLICATE KEY UPDATE
	NODE_NM 		= NEW.NODE_NM

	, SELF_ATTD_APPRV_YN = CASE WHEN TB_SITE_NODE.NODE_CD = 'n1' THEN 'Y' ELSE TB_SITE_NODE.SELF_ATTD_APPRV_YN END
	, UPDATE_NO		= NEW.UPDATE_NO
	, UPDATE_DATE 	= NEW.UPDATE_DATE

/* Baim01Mapper.mergeSiteInfo */ INSERT INTO TB_SITE ( SITE_CD , SITE_NO , SITE_NM , CMPNY_CD , ADDR_1 , ADDR_2 , ZIP_CODE , STR_DATE , END_DATE , USE_YN , SITE_ADMIN_CD , TEL_NO , GPS_RANGE , SITE_DESC , LAT , LON , INSERT_NO , INSERT_DATE , UPDATE_NO , UPDATE_DATE ) VALUES ( #{siteCd} , #{siteNo} , #{siteNm} , #{gvCmpnyCd} , #{addr1} , #{addr2} , #{zipCode} , REPLACE(#{strDate}, '-', '')
, REPLACE(#{endDate}, '-', '') NULL
, #{useYn} , #{siteAdminCd} , REPLACE(#{telNo}, '-', '') , #{gpsRange} , #{siteDesc} , #{lat} , #{lon} , #{gvUserCd} , NOW() , #{gvUserCd} , NOW() ) AS NEW ON DUPLICATE KEY UPDATE SITE_NO = NEW.SITE_NO , SITE_NM = NEW.SITE_NM , ADDR_1 = NEW.ADDR_1 , ADDR_2 = NEW.ADDR_2 , ZIP_CODE = NEW.ZIP_CODE , STR_DATE = NEW.STR_DATE , END_DATE = NEW.END_DATE , USE_YN = IFNULL(NEW.USE_YN, 'Y') , SITE_ADMIN_CD = NEW.SITE_ADMIN_CD , TEL_NO = NEW.TEL_NO , GPS_RANGE = NEW.GPS_RANGE , SITE_DESC = NEW.SITE_DESC , LAT = NEW.LAT , LON = NEW.LON , UPDATE_NO = NEW.UPDATE_NO , UPDATE_DATE = NEW.UPDATE_DATE

mapper.select:
/* Baim01Mapper.selectSiteLinkSrcCmpny */
SELECT A.LINK_SRC_CMPNY_CD
FROM TB_SITE A
WHERE A.CMPNY_CD = #{gvCmpnyCd}
  AND A.SITE_CD  = #{siteCd}

mapper.update:
/* Baim01Mapper.updateSiteAdminOnly */
UPDATE TB_SITE
   SET SITE_ADMIN_CD = #{siteAdminCd}
     , UPDATE_NO     = #{gvUserCd}
     , UPDATE_DATE   = NOW()
 WHERE CMPNY_CD = #{gvCmpnyCd}
   AND SITE_CD  = #{siteCd}
   AND LINK_SRC_CMPNY_CD IS NOT NULL
